import { CommonModule, Location } from '@angular/common';
import { ChangeDetectorRef, Component } from '@angular/core';
import { IconComponent } from '../../../shared/components/icon/icon.component';
import { SearchComponent } from '../../../shared/components/search/search.component';
import { MatMenuModule } from '@angular/material/menu';
import { HeaderService } from '../../services/header/header.service';
import { ProfileComponent } from '../../../shared/components/profile/profile.component';
import { ButtonComponent } from '../../../shared/components/button/button.component';
import { CommunicationService } from '../../../shared/services/communication/communication.service';
import { UserNotificationComponent } from '../../../shared/components/user-notification/user-notification.component';
import { interval } from 'rxjs';

@Component({
  selector: 'app-header',
  standalone: true,
  imports: [CommonModule, IconComponent, SearchComponent, MatMenuModule, ButtonComponent, UserNotificationComponent],
  templateUrl: './header.component.html',
  styleUrl: './header.component.scss'
})
export class HeaderComponent {
  userNotificationVisible: boolean = false;
  cStatus: 'FS' | 'DS' | 'WS' | 'LS' | 'U' | 'I' | 'P' | 'H' | 'PRESENT-START' | 'PRESENT-USER-ADDED';
  constructor(public hs: HeaderService, private location: Location, private cs: CommunicationService, private cdr: ChangeDetectorRef) { }


  ngAfterViewInit(): void {
    //Called after ngAfterContentInit when the component's view has been initialized. Applies to components only.
    //Add 'implements AfterViewInit' to the class.
    // setTimeout(() => {
    //   if (this.hs.Casedetail?.isPresent) {
    //     this.cStatus = 'PRESENT-USER-ADDED'
    //   }
    // }, 500);

    const presentInterval = setInterval(() => {
      if (this?.hs?.Casedetail) {
        if (this.hs.Casedetail?.isPresent) {
          this.cStatus = 'PRESENT-USER-ADDED'
        }
        clearInterval(presentInterval);
      }
    }, 1000);

  }
  goBack() {
    this.location.back();
  }

  gohome() {
    this.hs.goUserHome();
  }


  download() {
    this.cs.callFunction("DOWNLOAD-FILE");
  }

  notificationEvent(event) {
    if (event?.event === 'NOTIFICATION') {
      this.userNotificationVisible = event.data.userNotificationVisible;
      this.cdr.detectChanges();
    }
  }

}
