import { ChangeDetectionStrategy, ChangeDetectorRef, Component, EventEmitter, Input, Output } from '@angular/core';
import { SocketService } from '../../../core/services/socket/socket.service';
import { Subscription } from 'rxjs';
import { ButtonComponent } from '../button/button.component';
import { Router } from '@angular/router';
import { CommunicationService } from '../../services/communication/communication.service';
import { HeaderService } from '../../../core/services/header/header.service';
import { toolEvents } from '../../../pdf/interfaces/pdf.interface';
import { presentEvents } from '../../../presentation/interfaces/present.tool.interface';

@Component({
  selector: 'user-notification',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [ButtonComponent],
  templateUrl: './user-notification.component.html',
  styleUrl: './user-notification.component.scss'
})
export class UserNotificationComponent {
  @Input() userNotificationVisible: boolean = false;
  @Output() userNotificationVisibleChange: EventEmitter<boolean> = new EventEmitter<boolean>();
  @Output() emitEvent: EventEmitter<toolEvents> = new EventEmitter();
  userNotificationSubscribe: Subscription;


  @Input() cStatus: 'FS' | 'DS' | 'WS' | 'LS' | 'U' | 'I' | 'P' | 'H' | 'PRESENT-START' | 'PRESENT-USER-ADDED';
  @Input() notificationObj: any = {};
  constructor(private ss: SocketService, private cdr: ChangeDetectorRef,
    private router: Router, private CMS: CommunicationService, private hs: HeaderService) {
    this.ngOnDestroy();
    this.userNotificationSubscribe = this.ss.getUserNotifications().subscribe((res: any) => {
      try {
        debugger;
        if (res?.nCaseid && hs.Casedetail?.nCaseid == res?.nCaseid) {
          console.warn('USER NOTIFICATION', res)
          if (res?.cType == 'PRESENT-USER-ADDED') {
            this.cStatus = res?.cType;
            this.notificationObj = res;
            this.userNotificationVisible = true;
            this.emitEvent.emit({ event: 'NOTIFICATION', data: { userNotificationVisible: this.userNotificationVisible } });
          } else if (res?.cType == 'PRESENT-START') {
            this.cStatus = res?.cType;
            this.notificationObj = res;
            this.userNotificationVisible = true;
            this.emitEvent.emit({ event: 'NOTIFICATION', data: { userNotificationVisible: this.userNotificationVisible } });
          }
          else if (['LS', 'FS', 'DS', 'WS', 'TASK-SHARE', 'CS', "TR"].includes(res?.cType)) {
            this.CMS.callFunction({ event: 'NOTIFICATION', data: res })
          }
        }
      } catch (error) {
        console.error(error)
      }
      this.cdr.detectChanges();
    })

    this.ss.getPresentationTools().subscribe((res: presentEvents) => {
      if (['LIVE', 'USER-MANAGE', 'END'].includes(res?.event)) {
        if (((res?.event == 'USER-MANAGE' && res?.data?.cStatus == 'A' && res?.data?.cPermission == 'D') || res?.event == 'END') && (res?.data?.nPresentid == this.hs.Casedetail?.nPresentid || this.notificationObj?.nPresentid == res?.data?.nPresentid)) {
          this.cStatus = null;
          this.cdr.detectChanges();
        }
        // this.getOngoingList();
        // this.changeHandler.emit('refetch');
      }
    });
  }

  ngOnDestroy(): void {
    try {
      if (this.userNotificationSubscribe) {
        this.userNotificationSubscribe.unsubscribe();
      }
    } catch (error) {
    }
  }

  Close() {
    // this.cStatus = null;
    // this.notificationObj = {};
    this.userNotificationVisible = false;
    this.emitEvent.emit({ event: 'NOTIFICATION', data: { userNotificationVisible: this.userNotificationVisible } });
    this.cdr.detectChanges();
  }

  GoToPresentation() {
    if (this.userNotificationVisible == false && !this.notificationObj?.nPresentid) {
      this.notificationObj.nCaseid = this.hs.Casedetail?.nCaseid;
      this.notificationObj.nPresentid = this.hs.Casedetail?.nPresentid;
    }
    this.router.navigateByUrl(
      `/individual/doc/${encodeURIComponent(
        JSON.stringify([[], this.notificationObj.nCaseid, this.notificationObj.nPresentid])
      )}`
    );
    this.Close();
  }

}
